  const complete = async () => { if (!selected || !diagnosis.trim()) { setMessage('Enter a diagnosis before completing the consultation.'); return } try { await api.consultation({ caseId: String(selected.id), clinicalAssessment: assessment, diagnosis: [{ name: diagnosis }], clinicalNotes: assessment, investigations: [], treatmentPlan: plan, status: 'COMPLETED' }); setMessage('Consultation completed and added to the patient record.'); setCases(cases.filter(item => item.id !== selected.id)); setSelected(null) } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to complete consultation') } }
